-- Đồng bộ lớp khu_vuc từ Tree.gpkg lên SQL Server (MS SQL Server)
-- Nguồn: Tree.gpkg, lớp khu_vuc (5 khu, cắt theo trục đường nội bộ, mục 83 file thảo luận)
-- Thực hiện:
--   1. Sao lưu bảng khu_vuc hiện tại (3 khu nháp 1 m²)
--   2. Xóa khu nháp, chèn 5 khu với đúng ma_khu_vuc 1 - 5 (IDENTITY_INSERT)
--   3. Tính lại dien_tich (đơn vị: ha) = STArea() / 10000 (STArea trả về m² trên EPSG:3405)
--   4. Gán ma_khu_vuc cho cây bằng STContains
-- Tên khu và người quản lý là dữ liệu GIẢ ĐỊNH.
-- Chạy: sqlcmd -S localhost\SQLEXPRESS -U sa -P 123 -C -f 65001 -i "<đường dẫn>\db\04_dong_bo_khu_vuc.sql"

USE ie402_green_space;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

IF OBJECT_ID('khu_vuc_backup_nhap') IS NULL
    SELECT * INTO khu_vuc_backup_nhap FROM khu_vuc;

-- Không cây nào đang tham chiếu khu nháp (ma_khu_vuc của cay_xanh đều NULL)
UPDATE cay_xanh SET ma_khu_vuc = NULL WHERE ma_khu_vuc IS NOT NULL;
DELETE FROM khu_vuc;

SET IDENTITY_INSERT khu_vuc ON;
