FROM cay_xanh c
JOIN khu_vuc k ON k.shape.STContains(c.shape) = 1;

-- Kiểm tra trước khi COMMIT: mọi khu hợp lệ, mọi cây có đúng 1 khu
IF EXISTS (SELECT 1 FROM khu_vuc WHERE shape.STIsValid() = 0)
    THROW 50001, N'Có khu vực không hợp lệ', 1;
IF EXISTS (SELECT 1 FROM cay_xanh WHERE ma_khu_vuc IS NULL)
    THROW 50002, N'Còn cây chưa được gán khu vực', 1;
IF EXISTS (SELECT 1 FROM cay_xanh c JOIN khu_vuc k ON k.shape.STIntersects(c.shape) = 1
           GROUP BY c.ma_cay HAVING COUNT(*) > 1)
    THROW 50003, N'Có cây thuộc hơn một khu vực', 1;

COMMIT;
GO

SELECT k.ma_khu_vuc, k.ten_khu_vuc, n.ten_nql,
       CAST(k.dien_tich AS DECIMAL(8,2)) AS dien_tich_ha,
       COUNT(c.ma_cay) AS so_cay,
       CAST(COUNT(c.ma_cay) / k.dien_tich AS DECIMAL(6,2)) AS mat_do_cay_ha
FROM khu_vuc k
JOIN nguoi_quan_ly n ON n.ma_nql = k.ma_nql
LEFT JOIN cay_xanh c ON c.ma_khu_vuc = k.ma_khu_vuc
GROUP BY k.ma_khu_vuc, k.ten_khu_vuc, n.ten_nql, k.dien_tich
ORDER BY k.ma_khu_vuc;
